"""topcover_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 1 extrusion(s) and 5 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python topcover_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Face, Solid, Vector, Wire
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 3.0    # level along y
hole_d1 = 5.0
hole_d2 = 45.0

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 3.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(-26.5, 25.0), P(26.5, 25.0)),
    Edge.makeThreePointArc(P(26.5, 25.0), P(31.0963, 22.8567), P(32.5, 19.0)),
    cf.segment(P(32.5, 19.0), P(32.5, -19.0)),
    Edge.makeThreePointArc(P(32.5, -19.0), P(31.0963, -22.8567), P(26.5, -25.0)),
    cf.segment(P(26.5, -25.0), P(-26.5, -25.0)),
    Edge.makeThreePointArc(P(-26.5, -25.0), P(-31.0963, -22.8567), P(-32.5, -19.0)),
    cf.segment(P(-32.5, -19.0), P(-32.5, 19.0)),
    Edge.makeThreePointArc(P(-32.5, 19.0), P(-31.0963, 22.8567), P(-26.5, 25.0)),
)
part = prism(outline_1, z0, z1)

# ---- round holes: (x, z, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (-26.5, -19.0, hole_d1, z0, z1),
    (-26.5, 19.0, hole_d1, z0, z1),
    (26.5, -19.0, hole_d1, z0, z1),
    (26.5, 19.0, hole_d1, z0, z1),
    (0.0, 0.0, hole_d2, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- revolved features about axes along y: a profile in the half plane through the
# axis (u = distance from the axis, v = level), revolved 360 degrees --------------
RADIAL = (1, 0, 0)


def revolved(axis, rings):
    """Profile rings (outline first, then holes) revolved about the axis through axis along DIR."""
    face = Face.makeFromWires(Wire.assembleEdges(rings[0]), [Wire.assembleEdges(r) for r in rings[1:]])
    return Solid.revolve(face, 360.0, Vector(*axis), Vector(*axis) + Vector(*DIR))

# revolved boss 1
for a, b in [(0.0, 0.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeThreePointArc(Q(7.0, 11.42), Q(10.0766, 10.8778), Q(12.7817, 9.3173)),
            Edge.makeLine(Q(12.7817, 9.3173), Q(18.6455, 4.4018)),
            Edge.makeThreePointArc(Q(18.6455, 4.4018), Q(20.4479, 3.3618), Q(22.5, 3.0)),
            Edge.makeLine(Q(22.5, 3.0), Q(24.0, 3.0)),
            Edge.makeLine(Q(24.0, 3.0), Q(24.0, 0.0)),
            Edge.makeLine(Q(24.0, 0.0), Q(22.5, 0.0)),
            Edge.makeThreePointArc(Q(22.5, 0.0), Q(19.4218, 0.5428), Q(16.7183, 2.1027)),
            Edge.makeLine(Q(16.7183, 2.1027), Q(10.8545, 7.0182)),
            Edge.makeThreePointArc(Q(10.8545, 7.0182), Q(9.0505, 8.0587), Q(7.0, 8.42)),
            Edge.makeLine(Q(7.0, 8.42), Q(7.0, 11.42)),
        ],
    ]
    part = part + revolved(axis, rings)

# revolved cut 2 (4 axes)
for a, b in [(26.5, 19.0), (26.5, -19.0), (-26.5, -19.0), (-26.5, 19.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeLine(Q(2.5, 1.5), Q(2.5, 3.0)),
            Edge.makeLine(Q(2.5, 3.0), Q(4.0, 3.0)),
            Edge.makeLine(Q(4.0, 3.0), Q(2.5, 1.5)),
        ],
    ]
    part = part - revolved(axis, rings)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "topcover_exact.step")
